class Solution:
    def minimumAbsDifference(self, arr: list[int]) -> list[list[int]]:
        arr.sort()
        min_diff = min(arr[i] - arr[i - 1] for i in range(1, len(arr)))
        return [[arr[i - 1], arr[i]] for i in range(1, len(arr)) if arr[i] - arr[i - 1] == min_diff]

class Solution {
public:
    std::vector<std::vector<int>> minimumAbsDifference(std::vector<int>& arr) {
        std::sort(arr.begin(), arr.end());
        int minDiff = 2e9;
        for (int i = 1; i < arr.size(); ++i) {
            minDiff = std::min(minDiff, arr[i] - arr[i - 1]);
        }
        std::vector<std::vector<int>> res;
        for (int i = 1; i < arr.size(); ++i) {
            if (arr[i] - arr[i - 1] == minDiff) {
                res.push_back({arr[i - 1], arr[i]});
            }
        }
        return res;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> minimumAbsDifference(int[] arr) {
        java.util.Arrays.sort(arr);
        int minDiff = Integer.MAX_VALUE;
        for (int i = 1; i < arr.length; i++) {
            minDiff = Math.min(minDiff, arr[i] - arr[i - 1]);
        }
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] - arr[i - 1] == minDiff) {
                res.add(java.util.List.of(arr[i - 1], arr[i]));
            }
        }
        return res;
    }
}

